```python
import time
from collections import OrderedDict


class LRUCache:
    def __init__(self, capacity, ttl=None, clock=time.monotonic):
        if capacity < 1:
            raise ValueError("capacity must be >= 1")
        self.capacity = capacity
        self.ttl = ttl
        self.clock = clock
        self._data = OrderedDict()  # key -> (value, expires_at or None); oldest first

    def _expired(self, expires_at, now):
        return expires_at is not None and now >= expires_at

    def _sweep(self, now):
        if self.ttl is None:
            return
        for key in [k for k, (_, exp) in self._data.items() if self._expired(exp, now)]:
            del self._data[key]

    def get(self, key, default=None):
        now = self.clock()
        try:
            value, exp = self._data[key]
        except KeyError:
            return default
        if self._expired(exp, now):
            del self._data[key]
            return default
        self._data.move_to_end(key)
        return value

    def put(self, key, value):
        now = self.clock()
        self._sweep(now)
        expires_at = None if self.ttl is None else now + self.ttl
        self._data[key] = (value, expires_at)
        self._data.move_to_end(key)
        while len(self._data) > self.capacity:
            self._data.popitem(last=False)

    def __len__(self):
        if self.ttl is None:
            return len(self._data)
        now = self.clock()
        return sum(1 for (_, exp) in self._data.values() if not self._expired(exp, now))

    def __contains__(self, key):
        entry = self._data.get(key)
        if entry is None:
            return False
        return not self._expired(entry[1], self.clock())
```

Wait, one subtle point in put: if a key already exists and we re-put at a new time—after the sweep it should be fine. Also, if the re-put key itself is expired... the sweep already deleted it.

Another subtle point: `_sweep` uses list comprehension over items; no problem.

